CREATE TABLE IF NOT EXISTS addresses (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL, full_name VARCHAR(150) NOT NULL, phone VARCHAR(30) NOT NULL, line1 VARCHAR(250) NOT NULL, line2 VARCHAR(250), city VARCHAR(100) NOT NULL, state VARCHAR(100) NOT NULL, postal_code VARCHAR(10) NOT NULL, country VARCHAR(80) NOT NULL DEFAULT 'India');
CREATE TABLE IF NOT EXISTS carts (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS cart_items (id BIGSERIAL PRIMARY KEY, cart_id BIGINT NOT NULL REFERENCES carts(id) ON DELETE CASCADE, product_id BIGINT NOT NULL, quantity INT NOT NULL CHECK(quantity > 0), unit_price NUMERIC(18,2) NOT NULL, UNIQUE(cart_id, product_id));
CREATE TABLE IF NOT EXISTS orders (id BIGSERIAL PRIMARY KEY, order_number VARCHAR(80) NOT NULL UNIQUE, user_id BIGINT NOT NULL, subtotal NUMERIC(18,2) NOT NULL, discount NUMERIC(18,2) NOT NULL DEFAULT 0, shipping_charge NUMERIC(18,2) NOT NULL DEFAULT 0, total_amount NUMERIC(18,2) NOT NULL, payment_status VARCHAR(40) NOT NULL, order_status VARCHAR(40) NOT NULL, payment_method VARCHAR(40) NOT NULL, estimated_delivery_from TIMESTAMPTZ NOT NULL, estimated_delivery_to TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS order_items (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id BIGINT NOT NULL, product_name VARCHAR(200) NOT NULL, product_sku VARCHAR(80) NOT NULL, quantity INT NOT NULL, unit_price NUMERIC(18,2) NOT NULL, total_price NUMERIC(18,2) NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL, payment_gateway VARCHAR(40) NOT NULL, transaction_id VARCHAR(200), gateway_order_id VARCHAR(200), amount NUMERIC(18,2) NOT NULL, status VARCHAR(40) NOT NULL, payment_method VARCHAR(80), gateway_response TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, user_id BIGINT, action VARCHAR(100) NOT NULL, entity_type VARCHAR(100) NOT NULL, entity_id VARCHAR(200), old_value TEXT, new_value TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
